def compute(vars):
    net_interest_income = vars["v1"]
    total_net_revenue = vars["v2"]

    if total_net_revenue == 0:
        return None

    percentage = (net_interest_income / total_net_revenue) * 100

    return {
        "value": percentage,
        "trace": {
            "net_interest_income": net_interest_income,
            "total_net_revenue": total_net_revenue,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
